const { MongoClient } = require('mongodb');
require('dotenv').config()

class CampaignManager {
  /**
   * @param {string} uri - MongoDB connection string with a db name
   * @param {string} dbName - Database name
   */
  constructor(uri) {
    this.client = new MongoClient(uri, {
      maxPoolSize: 50, // Allows up to 50 concurrent socket connections for high webhook traffic
      minPoolSize: 10
    });
    this.db = null;
    this.campaigns = null;
    this.responses = null;
  }

  /**
   * Initializes the database connection and enforces indexes.
   */
  async connect() {
    if (!this.db) {
      await this.client.connect();
      this.db = this.client.db();
      
      // Collection definitions
      this.campaigns = this.db.collection('campaigns');
      this.responses = this.db.collection('campaign_responses');

      //this is verry CRITICAL: Ensure compound indexes exist for sub-millisecond lookups
      await this.campaigns.createIndex({ campaignId: 1 }, { unique: true });
      await this.responses.createIndex({ campaignId: 1, phoneNumber: 1 }, { unique: true });
    }
  }

  /**
   * Gracefully closes the database connection pool.
   */
  async disconnect() {
    if (this.client) {
      await this.client.close();
    }
  }

  /**
   * Creates a campaign profile if it does not already exist.
   * @param {string} campaignId - Unique campaign identifier
   * @param {Object} metadata - Optional extra data (name, description, totalQuestions)
   */
  async createCampaignIfNotExist(campaignId, metadata = {}) {
    const update = {
      $setOnInsert: {
        campaignId,
        createdAt: new Date().toISOString(),
        status: 'active',
        ...metadata
      }
    };
    // upsert: true makes this a safe, non-destructive create-if-not-exist query
    await this.campaigns.updateOne({ campaignId }, update, { upsert: true });
  }

  /**
   * Initiates a brand new response profile for a specific phone number.
   * Resets any older attempts if they exist.
   * @param {string} campaignId 
   * @param {string} phoneNumber 
   */
  async initiateResponseProfile(campaignId, phoneNumber) {
    const profile = {
      campaignId,
      phoneNumber,
      startedAt: new Date().toISOString(),
      lastUpdatedAt: new Date().toISOString(),
      status: 'in-progress',
      responses: {} // Using key-value map structure for safe direct targeting
    };

    // overwrite/replace existing profile to clear previous session data cleanly
    await this.responses.replaceOne(
      { campaignId, phoneNumber },
      profile,
      { upsert: true }
    );
  }

  /**
   * Atomically records a single answer to a specific question for a phone number.
   * @param {string} campaignId 
   * @param {string} phoneNumber 
   * @param {string} questionId - e.g., "q_01", "q_02"
   * @param {Object} responsePayload - Object containing text, type, rawData, etc.
   */
  async addResponse(campaignId, phoneNumber, questionId, responsePayload) {
    const update = {
      $set: {
        lastUpdatedAt: new Date().toISOString(),
        // Dynamically creates/updates the property matching the exact question identifier
        [`responses.${questionId}`]: {
          ...responsePayload,
          receivedAt: new Date().toISOString()
        }
      }
    };

    const result = await this.responses.updateOne(
      { campaignId, phoneNumber },
      update,
      { upsert: false } // Assumes profile was initiated. Set true if you want to skip explicit initialization.
    );

    if (result.matchedCount === 0) {
      throw new Error(`Cannot add response. Profile for ${phoneNumber} in campaign ${campaignId} was not initiated.`);
    }
  }
}

module.exports = CampaignManager;
